import { NextApiRequest, NextApiResponse } from "next";

import prisma from "@/lib/prisma";

export default async function handle(
  req: NextApiRequest,
  res: NextApiResponse,
) {
  // We only allow POST requests
  if (req.method !== "POST") {
    res.status(405).json({ message: "Method Not Allowed" });
    return;
  }

  // POST /api/record_reaction

  const { viewId, pageNumber, type } = req.body as {
    viewId: string;
    pageNumber: number;
    type: string;
  };

  try {
    const reaction = await prisma.reaction.create({
      data: {
        viewId,
        pageNumber,
        type,
      },
    });

    if (!reaction) {
      res.status(500).json({ message: "Internal Server Error" });
      return;
    }

    res.status(200).json({ message: "Reaction recorded" });
    return;
  } catch (error) {
    res.status(500).json({ message: "Internal Server Error" });
    return;
  }
}

import { createHash } from "crypto";

export const hashToken = (
  token: string,
  {
    noSecret = false,
  }: {
    noSecret?: boolean;
  } = {},
) => {
  return createHash("sha256")
    .update(`${token}${noSecret ? "" : process.env.NEXTAUTH_SECRET}`)
    .digest("hex");
};

import { NextApiRequest, NextApiResponse } from "next";

import { getToken } from "next-auth/jwt";

const VERCEL_DEPLOYMENT = !!process.env.VERCEL_URL;

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse,
) {
  const token = await getToken({ req });

  if (!token) {
    return res.status(401).end();
  }

  // Set the cookie for the other domain
  res.setHeader(
    "Set-Cookie",
    `${VERCEL_DEPLOYMENT ? "__Secure-" : ""}next-auth.session-token=${req.cookies[`${VERCEL_DEPLOYMENT ? "__Secure-" : ""}next-auth.session-token`]}; HttpOnly; Path=/; SameSite=Lax; ${VERCEL_DEPLOYMENT ? "Secure; " : ""}Domain=.papermark.io; Max-Age=${30 * 24 * 60 * 60}`,
  );

  res.status(200).end();
}

import { type Session } from "next-auth";

import hanko from "@/lib/hanko";
import prisma from "@/lib/prisma";
import { CustomUser } from "@/lib/types";

export async function startServerPasskeyRegistration({
  session,
}: {
  session: Session;
}) {
  if (!session) throw new Error("Not logged in");

  const sessionUser = session.user as CustomUser;

  const user = await prisma.user.findUnique({
    where: { email: sessionUser.email as string },
    select: { id: true, name: true },
  });

  const createOptions = await hanko.registration.initialize({
    userId: user!.id,
    username: user!.name || user!.id,
  });

  return createOptions;
}

// This is *your* server-side code; you need to implement this yourself.
// NextAuth takes care of logging in the user after they have registered their passkey.
export async function finishServerPasskeyRegistration({
  credential,
  session,
}: {
  credential: any;
  session: Session;
}) {
  if (!session) throw new Error("Not logged in");

  await hanko.registration.finalize(credential);

  // const sessionUser = session.user as CustomUser;

  // Now the user has registered their passkey and can use it to log in.

  // const user = await prisma.user.update({
  //   where: { email: sessionUser.email as string },
  //   select: { id: true },
  // });
}

export async function listUserPasskeys({ session }: { session: Session }) {
  if (!session) throw new Error("Not logged in");

  const sessionUser = session.user as CustomUser;

  const user = await prisma.user.findUnique({
    where: { email: sessionUser.email as string },
    select: { id: true },
  });

  if (!user) throw new Error("User not found");

  const tenantId = process.env.NEXT_PUBLIC_HANKO_TENANT_ID;
  const apiKey = process.env.HANKO_API_KEY;

  if (!tenantId || !apiKey) {
    throw new Error("Passkey service configuration missing");
  }
  const response = await fetch(
    `https://passkeys.hanko.io/${tenantId}/credentials?user_id=${user.id}`,
    {
      method: "GET",
      headers: {
        apiKey: apiKey,
        "Content-Type": "application/json",
      },
    },
  );

  if (!response.ok) {
    throw new Error(`Failed to list passkeys: ${response.statusText}`);
  }

  const passkeys = await response.json();

  if (!Array.isArray(passkeys)) {
    throw new Error("Invalid passkey data received");
  }

  return passkeys;
}

export async function removeUserPasskey({
  credentialId,
  session,
}: {
  credentialId: string;
  session: Session;
}) {
  if (!session) throw new Error("Not logged in");

  // First verify the credential belongs to the user
  const sessionUser = session.user as CustomUser;
  const user = await prisma.user.findUnique({
    where: { email: sessionUser.email as string },
    select: { id: true },
  });

  if (!user) throw new Error("User not found");

  // Verify ownership by listing user's passkeys first
  const userPasskeys = await listUserPasskeys({ session });
  const ownsCredential = userPasskeys.some((pk: any) => pk.id === credentialId);

  if (!ownsCredential) {
    throw new Error("Unauthorized");
  }

  const tenantId = process.env.NEXT_PUBLIC_HANKO_TENANT_ID;
  const apiKey = process.env.HANKO_API_KEY;

  if (!tenantId || !apiKey) {
    throw new Error("Passkey service configuration missing");
  }

  const isValidCredentialId = /^[a-zA-Z0-9_-]+$/.test(credentialId);
  if (!isValidCredentialId) {
    throw new Error("Invalid credential ID format");
  }

  const response = await fetch(
    `https://passkeys.hanko.io/${tenantId}/credentials/${credentialId}`,
    {
      method: "DELETE",
      headers: {
        apiKey: apiKey,
        "Content-Type": "application/json",
      },
    },
  );

  if (!response.ok) {
    throw new Error(`Failed to remove passkey: ${response.statusText}`);
  }
}

import { PrismaAdapter } from "@next-auth/prisma-adapter";
import PasskeyProvider from "@teamhanko/passkeys-next-auth-provider";
import NextAuth, { type NextAuthOptions } from "next-auth";
import EmailProvider from "next-auth/providers/email";
import GoogleProvider from "next-auth/providers/google";
import LinkedInProvider from "next-auth/providers/linkedin";

import { identifyUser, trackAnalytics } from "@/lib/analytics";
import { isBlacklistedEmail } from "@/lib/edge-config/blacklist";
import { sendVerificationRequestEmail } from "@/lib/emails/send-verification-request";
import { sendWelcomeEmail } from "@/lib/emails/send-welcome";
import hanko from "@/lib/hanko";
import prisma from "@/lib/prisma";
import { CreateUserEmailProps, CustomUser } from "@/lib/types";
import { subscribe } from "@/lib/unsend";
import { generateChecksum } from "@/lib/utils/generate-checksum";

const VERCEL_DEPLOYMENT = !!process.env.VERCEL_URL;

function getMainDomainUrl(): string {
  if (process.env.NODE_ENV === "development") {
    return process.env.NEXTAUTH_URL || "http://localhost:3000";
  }
  return process.env.NEXTAUTH_URL || "https://app.papermark.com";
}

// This function can run for a maximum of 180 seconds
export const config = {
  maxDuration: 180,
};

export const authOptions: NextAuthOptions = {
  pages: {
    error: "/login",
  },
  providers: [
    GoogleProvider({
      clientId: process.env.GOOGLE_CLIENT_ID as string,
      clientSecret: process.env.GOOGLE_CLIENT_SECRET as string,
      allowDangerousEmailAccountLinking: true,
    }),
    LinkedInProvider({
      clientId: process.env.LINKEDIN_CLIENT_ID as string,
      clientSecret: process.env.LINKEDIN_CLIENT_SECRET as string,
      authorization: {
        params: { scope: "openid profile email" },
      },
      issuer: "https://www.linkedin.com/oauth",
      jwks_endpoint: "https://www.linkedin.com/oauth/openid/jwks",
      profile(profile, tokens) {
        const defaultImage =
          "https://cdn-icons-png.flaticon.com/512/174/174857.png";
        return {
          id: profile.sub,
          name: profile.name,
          email: profile.email,
          image: profile.picture ?? defaultImage,
        };
      },
      allowDangerousEmailAccountLinking: true,
    }),
    EmailProvider({
      async sendVerificationRequest({ identifier, url }) {
        const hasValidNextAuthUrl = !!process.env.NEXTAUTH_URL;
        let finalUrl = url;

        if (!hasValidNextAuthUrl) {
          const mainDomainUrl = getMainDomainUrl();
          const urlObj = new URL(url);
          const mainDomainObj = new URL(mainDomainUrl);
          urlObj.hostname = mainDomainObj.hostname;
          urlObj.protocol = mainDomainObj.protocol;
          urlObj.port = mainDomainObj.port || "";

          finalUrl = urlObj.toString();
        }

        if (process.env.NODE_ENV === "development") {
          const checksum = generateChecksum(finalUrl);
          const verificationUrlParams = new URLSearchParams({
            verification_url: finalUrl,
            checksum,
          });

          const baseUrl = hasValidNextAuthUrl
            ? process.env.NEXTAUTH_URL
            : getMainDomainUrl();

          const verificationUrl = `${baseUrl}/verify?${verificationUrlParams}`;
          console.log("[Login URL]", verificationUrl);
          return;
        } else {
          await sendVerificationRequestEmail({
            url: finalUrl,
            email: identifier,
          });
        }
      },
    }),
    PasskeyProvider({
      tenant: hanko,
      async authorize({ userId }) {
        const user = await prisma.user.findUnique({ where: { id: userId } });
        if (!user) return null;
        return user;
      },
    }),
  ],
  adapter: PrismaAdapter(prisma),
  session: { strategy: "jwt" },
  cookies: {
    sessionToken: {
      name: `${VERCEL_DEPLOYMENT ? "__Secure-" : ""}next-auth.session-token`,
      options: {
        httpOnly: true,
        sameSite: "lax",
        path: "/",
        // When working on localhost, the cookie domain must be omitted entirely (https://stackoverflow.com/a/1188145)
        domain: VERCEL_DEPLOYMENT ? ".papermark.com" : undefined,
        secure: VERCEL_DEPLOYMENT,
      },
    },
  },
  callbacks: {
    signIn: async ({ user }) => {
      if (!user.email || (await isBlacklistedEmail(user.email))) {
        await identifyUser(user.email ?? user.id);
        await trackAnalytics({
          event: "User Sign In Attempted",
          email: user.email ?? undefined,
          userId: user.id,
        });
        return false;
      }
      return true;
    },

    jwt: async (params) => {
      const { token, user, trigger } = params;
      if (!token.email) {
        return {};
      }
      if (user) {
        token.user = user;
      }
      // refresh the user data
      if (trigger === "update") {
        const user = token?.user as CustomUser;
        const refreshedUser = await prisma.user.findUnique({
          where: { id: user.id },
        });
        if (refreshedUser) {
          token.user = refreshedUser;
        } else {
          return {};
        }

        if (refreshedUser?.email !== user.email) {
          // if user has changed email, delete all accounts for the user
          if (user.id && refreshedUser.email) {
            await prisma.account.deleteMany({
              where: { userId: user.id },
            });
          }
        }
      }
      return token;
    },
    session: async ({ session, token }) => {
      (session.user as CustomUser) = {
        id: token.sub,
        // @ts-ignore
        ...(token || session).user,
      };
      return session;
    },
  },
  events: {
    async createUser(message) {
      const params: CreateUserEmailProps = {
        user: {
          name: message.user.name,
          email: message.user.email,
        },
      };

      await identifyUser(message.user.email ?? message.user.id);
      await trackAnalytics({
        event: "User Signed Up",
        email: message.user.email,
        userId: message.user.id,
      });

      await sendWelcomeEmail(params);

      if (message.user.email) {
        await subscribe(message.user.email);
      }
    },
    async signIn(message) {
      if (typeof window !== "undefined") {
        try {
          await fetch("/api/auth-plus/set-cookie");
        } catch (error) {
          console.error("Failed to set additional cookie", error);
        }
      }
      await identifyUser(message.user.email ?? message.user.id);
      await trackAnalytics({
        event: "User Signed In",
        email: message.user.email,
      });
    },
  },
};

export default NextAuth(authOptions);

import { NextApiRequest, NextApiResponse } from "next";

import { authOptions } from "@/pages/api/auth/[...nextauth]";
import { ItemType } from "@prisma/client";
import { getServerSession } from "next-auth";

import { errorhandler } from "@/lib/errorHandler";
import prisma from "@/lib/prisma";
import { CustomUser } from "@/lib/types";

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse,
) {
  if (req.method !== "POST") {
    res.setHeader("Allow", ["POST"]);
    return res.status(405).end(`Method ${req.method} Not Allowed`);
  }

  const session = await getServerSession(req, res, authOptions);
  if (!session) {
    return res.status(401).json({ message: "Unauthorized" });
  }

  const { teamId, id: dataroomId } = req.query as {
    teamId: string;
    id: string;
  };

  const userId = (session.user as CustomUser).id;

  try {
    const { documentIds, strategy, folderPath } = req.body as {
      documentIds: string[];
      strategy: string;
      folderPath?: string;
    };

    // Validate input
    if (
      !documentIds ||
      !Array.isArray(documentIds) ||
      documentIds.length === 0
    ) {
      return res.status(400).json({ message: "Document IDs are required" });
    }

    if (!strategy) {
      return res.status(400).json({ message: "Strategy is required" });
    }

    // Validate strategy
    if (
      !["INHERIT_FROM_PARENT", "ASK_EVERY_TIME", "HIDDEN_BY_DEFAULT"].includes(
        strategy,
      )
    ) {
      return res.status(400).json({ message: "Invalid strategy" });
    }

    // Check if the user is part of the team
    const team = await prisma.team.findFirst({
      where: {
        id: teamId,
        users: { some: { userId } },
      },
    });

    if (!team) {
      return res.status(403).json({ message: "Unauthorized" });
    }

    // Get dataroom and verify it exists and belongs to the team
    const dataroom = await prisma.dataroom.findUnique({
      where: { id: dataroomId },
      select: {
        id: true,
        teamId: true,
        defaultPermissionStrategy: true,
      },
    });

    if (!dataroom || dataroom.teamId !== teamId) {
      return res.status(404).json({ message: "Dataroom not found" });
    }

    // Get dataroom documents for the provided document IDs
    const dataroomDocuments = await prisma.dataroomDocument.findMany({
      where: {
        documentId: { in: documentIds },
        dataroomId,
      },
      select: { id: true, documentId: true, folderId: true },
    });

    if (dataroomDocuments.length === 0) {
      return res
        .status(404)
        .json({ message: "No documents found in this dataroom" });
    }

    // Apply permissions based on strategy
    await applyPermissionStrategy(
      dataroomId,
      dataroomDocuments,
      strategy,
      folderPath,
    );

    return res.status(200).json({
      message: "Permissions applied successfully",
      documentsProcessed: dataroomDocuments.length,
    });
  } catch (error) {
    errorhandler(error, res);
  }
}

async function applyPermissionStrategy(
  dataroomId: string,
  dataroomDocuments: {
    id: string;
    documentId: string;
    folderId: string | null;
  }[],
  strategy: string,
  folderPath?: string,
) {
  if (strategy === "INHERIT_FROM_PARENT") {
    const isRootLevel = !folderPath || folderPath.length === 0;

    if (isRootLevel) {
      // For root level, apply view-only permissions to all groups
      await applyRootLevelPermissions(dataroomId, dataroomDocuments);
    } else {
      // For subfolders, inherit from parent folder
      await inheritFromParentFolder(dataroomId, dataroomDocuments, folderPath);
    }
  } else if (strategy === "ASK_EVERY_TIME") {
    // Do nothing here - the UI will handle showing the permission modal
    return;
  } else if (strategy === "HIDDEN_BY_DEFAULT") {
    // Do nothing here - documents remain hidden with no permissions
    return;
  }
}

async function applyRootLevelPermissions(
  dataroomId: string,
  dataroomDocuments: {
    id: string;
    documentId: string;
    folderId: string | null;
  }[],
) {
  // Get both ViewerGroups and PermissionGroups
  const [viewerGroups, permissionGroups] = await Promise.all([
    prisma.viewerGroup.findMany({
      where: { dataroomId },
      select: { id: true },
    }),
    prisma.permissionGroup.findMany({
      where: { dataroomId },
      select: { id: true },
    }),
  ]);

  const viewerGroupPermissionsToCreate: any[] = [];
  const permissionGroupPermissionsToCreate: any[] = [];

  // ViewerGroup permissions - all get view-only access
  viewerGroups.forEach((group) => {
    dataroomDocuments.forEach((doc) => {
      viewerGroupPermissionsToCreate.push({
        groupId: group.id,
        itemId: doc.id,
        itemType: ItemType.DATAROOM_DOCUMENT,
        canView: true,
        canDownload: false,
      });
    });
  });

  // PermissionGroup permissions - all get view-only access
  permissionGroups.forEach((group) => {
    dataroomDocuments.forEach((doc) => {
      permissionGroupPermissionsToCreate.push({
        groupId: group.id,
        itemId: doc.id,
        itemType: ItemType.DATAROOM_DOCUMENT,
        canView: true,
        canDownload: false,
        canDownloadOriginal: false,
      });
    });
  });

  // Apply permissions in a transaction
  await prisma.$transaction(async (tx) => {
    // Create new permissions
    if (viewerGroupPermissionsToCreate.length > 0) {
      await tx.viewerGroupAccessControls.createMany({
        data: viewerGroupPermissionsToCreate,
        skipDuplicates: true,
      });
    }

    if (permissionGroupPermissionsToCreate.length > 0) {
      await tx.permissionGroupAccessControls.createMany({
        data: permissionGroupPermissionsToCreate,
        skipDuplicates: true,
      });
    }
  });
}

async function inheritFromParentFolder(
  dataroomId: string,
  dataroomDocuments: {
    id: string;
    documentId: string;
    folderId: string | null;
  }[],
  folderPath: string,
) {
  // Get parent folder permissions and apply them to new documents
  const pathSegments = folderPath.split("/").filter(Boolean);
  const parentPath = "/" + pathSegments.slice(0, -1).join("/");

  const parentFolder = await prisma.dataroomFolder.findUnique({
    where: {
      dataroomId_path: { dataroomId, path: parentPath },
    },
    select: { id: true },
  });

  if (!parentFolder) {
    // If no parent folder found, apply root level permissions
    await applyRootLevelPermissions(dataroomId, dataroomDocuments);
    return;
  }

  // Get existing permissions for the parent folder
  const [parentViewerPermissions, parentPermissionGroupPermissions] =
    await Promise.all([
      prisma.viewerGroupAccessControls.findMany({
        where: {
          itemId: parentFolder.id,
          itemType: ItemType.DATAROOM_FOLDER,
        },
        select: { groupId: true, canView: true, canDownload: true },
      }),
      prisma.permissionGroupAccessControls.findMany({
        where: {
          itemId: parentFolder.id,
          itemType: ItemType.DATAROOM_FOLDER,
        },
        select: {
          groupId: true,
          canView: true,
          canDownload: true,
          canDownloadOriginal: true,
        },
      }),
    ]);

  // Apply parent permissions to documents
  await prisma.$transaction(async (tx) => {
    // Create permissions based on parent folder permissions
    const viewerGroupPermissionsToCreate: any[] = [];
    const permissionGroupPermissionsToCreate: any[] = [];

    parentViewerPermissions.forEach((parentPerm) => {
      dataroomDocuments.forEach((doc) => {
        viewerGroupPermissionsToCreate.push({
          groupId: parentPerm.groupId,
          itemId: doc.id,
          itemType: ItemType.DATAROOM_DOCUMENT,
          canView: parentPerm.canView,
          canDownload: parentPerm.canDownload,
        });
      });
    });

    parentPermissionGroupPermissions.forEach((parentPerm) => {
      dataroomDocuments.forEach((doc) => {
        permissionGroupPermissionsToCreate.push({
          groupId: parentPerm.groupId,
          itemId: doc.id,
          itemType: ItemType.DATAROOM_DOCUMENT,
          canView: parentPerm.canView,
          canDownload: parentPerm.canDownload,
          canDownloadOriginal: parentPerm.canDownloadOriginal,
        });
      });
    });

    if (viewerGroupPermissionsToCreate.length > 0) {
      await tx.viewerGroupAccessControls.createMany({
        data: viewerGroupPermissionsToCreate,
        skipDuplicates: true,
      });
    }

    if (permissionGroupPermissionsToCreate.length > 0) {
      await tx.permissionGroupAccessControls.createMany({
        data: permissionGroupPermissionsToCreate,
        skipDuplicates: true,
      });
    }
  });
}

import { NextApiRequest, NextApiResponse } from "next";

import { ItemType } from "@prisma/client";
import { getServerSession } from "next-auth/next";

import { errorhandler } from "@/lib/errorHandler";
import prisma from "@/lib/prisma";
import { CustomUser } from "@/lib/types";

import { authOptions } from "../../../../../auth/[...nextauth]";

export default async function handle(
  req: NextApiRequest,
  res: NextApiResponse,
) {
  if (req.method === "GET") {
    // GET /api/teams/:teamId/datarooms/:id/permission-groups
    const session = await getServerSession(req, res, authOptions);
    if (!session) {
      return res.status(401).end("Unauthorized");
    }

    const { teamId, id: dataroomId } = req.query as {
      teamId: string;
      id: string;
    };

    const userId = (session.user as CustomUser).id;

    try {
      const team = await prisma.team.findUnique({
        where: {
          id: teamId,
          users: {
            some: { userId },
          },
        },
      });

      if (!team) {
        return res.status(401).end("Unauthorized");
      }

      const dataroom = await prisma.dataroom.findUnique({
        where: {
          id: dataroomId,
          teamId: teamId,
        },
      });

      if (!dataroom) {
        return res.status(404).json({ error: "Dataroom not found" });
      }

      const permissionGroups = await prisma.permissionGroup.findMany({
        where: {
          dataroomId: dataroomId,
          teamId: teamId,
        },
        orderBy: {
          createdAt: "desc",
        },
        include: {
          accessControls: true,
          links: {
            select: {
              id: true,
              name: true,
            },
          },
          _count: {
            select: {
              links: true,
              accessControls: true,
            },
          },
        },
      });

      return res.status(200).json(permissionGroups);
    } catch (error) {
      errorhandler(error, res);
    }
  } else if (req.method === "POST") {
    // POST /api/teams/:teamId/datarooms/:id/permission-groups
    const session = await getServerSession(req, res, authOptions);
    if (!session) {
      return res.status(401).end("Unauthorized");
    }

    const { teamId, id: dataroomId } = req.query as {
      teamId: string;
      id: string;
    };
    const { permissions, linkId } = req.body;

    const userId = (session.user as CustomUser).id;

    try {
      // Verify team membership
      const team = await prisma.team.findUnique({
        where: {
          id: teamId,
          users: {
            some: { userId },
          },
        },
      });

      if (!team) {
        return res.status(401).end("Unauthorized");
      }

      // Verify dataroom exists and belongs to team
      const dataroom = await prisma.dataroom.findUnique({
        where: {
          id: dataroomId,
          teamId: teamId,
        },
      });

      if (!dataroom) {
        return res.status(404).json({ error: "Dataroom not found" });
      }

      // Create permission group and access controls in a transaction
      const result = await prisma.$transaction(async (tx) => {
        // Create the permission group
        const permissionGroup = await tx.permissionGroup.create({
          data: {
            name: `Link Permissions ${Date.now()}`,
            description: "Auto-generated permission group for link",
            dataroomId: dataroomId,
            teamId: teamId,
          },
        });

        // Prepare access control data for batch insert
        const accessControlData = Object.entries(permissions).map(
          ([itemId, permission]) => {
            const perm = permission as {
              view: boolean;
              download: boolean;
              itemType: ItemType;
            };
            return {
              groupId: permissionGroup.id,
              itemId: itemId,
              itemType: perm.itemType,
              canView: perm.view,
              canDownload: perm.download,
              canDownloadOriginal: false,
            };
          },
        );

        // Create all access controls in a single batch operation
        await tx.permissionGroupAccessControls.createMany({
          data: accessControlData,
        });

        // Fetch the created access controls for return data
        const accessControls = await tx.permissionGroupAccessControls.findMany({
          where: {
            groupId: permissionGroup.id,
          },
        });

        // Update the link with the permission group
        if (linkId) {
          await tx.link.update({
            where: { id: linkId, teamId: teamId },
            data: {
              permissionGroupId: permissionGroup.id,
            },
          });
        }

        return {
          permissionGroup,
          accessControls,
        };
      });

      return res.status(200).json(result);
    } catch (error) {
      errorhandler(error, res);
    }
  }

  // We only allow GET and POST requests
  res.setHeader("Allow", ["GET", "POST"]);
  return res.status(405).end(`Method ${req.method} Not Allowed`);
}

import { NextApiRequest, NextApiResponse } from "next";

import { authOptions } from "@/pages/api/auth/[...nextauth]";
import { ItemType } from "@prisma/client";
import { getServerSession } from "next-auth/next";
import { z } from "zod";

import { errorhandler } from "@/lib/errorHandler";
import prisma from "@/lib/prisma";
import { CustomUser } from "@/lib/types";

// Zod schema for validating permissions
const itemPermissionSchema = z.object({
  view: z.boolean(),
  download: z.boolean(),
  itemType: z.nativeEnum(ItemType),
});

const permissionsSchema = z.record(z.string(), itemPermissionSchema);

const patchPermissionGroupSchema = z.object({
  name: z.string().optional(),
  description: z.string().optional(),
});

// Helper function to get parent folder IDs for a given document in a dataroom
async function getParentFolderIds(
  dataroomId: string,
  documentId: string,
): Promise<string[]> {
  // Get the dataroom document to find which folder it's in
  const dataroomDocument = await prisma.dataroomDocument.findUnique({
    where: { id: documentId },
    select: { folderId: true },
  });

  if (!dataroomDocument?.folderId) {
    return []; // Document is at root level
  }

  // Get the folder and walk up the hierarchy
  const parentFolders: string[] = [];
  let currentFolderId: string | null = dataroomDocument.folderId;

  while (currentFolderId) {
    parentFolders.push(currentFolderId);

    const folder: { parentId: string | null } | null =
      await prisma.dataroomFolder.findUnique({
        where: { id: currentFolderId },
        select: { parentId: true },
      });

    currentFolderId = folder?.parentId || null;
  }

  return parentFolders;
}

// Helper function to ensure parent folders are visible when child documents are made visible
async function ensureParentFoldersVisible(
  dataroomId: string,
  groupId: string,
  permissions: Record<
    string,
    { itemType: ItemType; view: boolean; download: boolean }
  >,
): Promise<void> {
  const foldersToMakeVisible = new Set<string>();

  // Find all documents that are being made visible
  const visibleDocuments = Object.entries(permissions)
    .filter(
      ([_, perm]) => perm.itemType === ItemType.DATAROOM_DOCUMENT && perm.view,
    )
    .map(([itemId, _]) => itemId);

  // Get parent folder IDs for all visible documents
  for (const documentId of visibleDocuments) {
    const parentFolders = await getParentFolderIds(dataroomId, documentId);
    parentFolders.forEach((folderId) => foldersToMakeVisible.add(folderId));
  }

  // Also handle folders that are being made visible - ensure their parent folders are visible too
  const visibleFolders = Object.entries(permissions)
    .filter(
      ([_, perm]) => perm.itemType === ItemType.DATAROOM_FOLDER && perm.view,
    )
    .map(([itemId, _]) => itemId);

  for (const folderId of visibleFolders) {
    let currentFolderId: string | null = folderId;

    while (currentFolderId) {
      const folder: { parentId: string | null } | null =
        await prisma.dataroomFolder.findUnique({
          where: { id: currentFolderId },
          select: { parentId: true },
        });

      if (folder?.parentId) {
        foldersToMakeVisible.add(folder.parentId);
        currentFolderId = folder.parentId;
      } else {
        break;
      }
    }
  }

  // Update or create permissions for parent folders to make them visible
  if (foldersToMakeVisible.size > 0) {
    const foldersToUpdate = Array.from(foldersToMakeVisible);

    await prisma.$transaction(async (tx) => {
      for (const folderId of foldersToUpdate) {
        await tx.permissionGroupAccessControls.upsert({
          where: {
            groupId_itemId: {
              groupId: groupId,
              itemId: folderId,
            },
          },
          create: {
            groupId: groupId,
            itemId: folderId,
            itemType: ItemType.DATAROOM_FOLDER,
            canView: true,
            canDownload: false,
            canDownloadOriginal: false,
          },
          update: {
            canView: true, // Always ensure parent folders are visible
            // Don't change canDownload - preserve existing setting
          },
        });
      }
    });
  }
}

export default async function handle(
  req: NextApiRequest,
  res: NextApiResponse,
) {
  if (req.method === "GET") {
    // GET /api/teams/:teamId/datarooms/:id/permission-groups/:permissionGroupId
    const session = await getServerSession(req, res, authOptions);
    if (!session) {
      return res.status(401).end("Unauthorized");
    }

    const {
      teamId,
      id: dataroomId,
      permissionGroupId,
    } = req.query as {
      teamId: string;
      id: string;
      permissionGroupId: string;
    };

    const userId = (session.user as CustomUser).id;

    try {
      // Verify team membership
      const team = await prisma.team.findUnique({
        where: {
          id: teamId,
          users: {
            some: { userId },
          },
        },
      });

      if (!team) {
        return res.status(401).end("Unauthorized");
      }

      // Verify dataroom exists and belongs to team
      const dataroom = await prisma.dataroom.findUnique({
        where: {
          id: dataroomId,
          teamId: teamId,
        },
      });

      if (!dataroom) {
        return res.status(404).json({ error: "Dataroom not found" });
      }

      // Fetch permission group and its access controls
      const permissionGroup = await prisma.permissionGroup.findUnique({
        where: {
          id: permissionGroupId,
          dataroomId: dataroomId,
          teamId: teamId,
        },
        include: {
          accessControls: true,
        },
      });

      if (!permissionGroup) {
        return res.status(404).json({ error: "Permission group not found" });
      }

      return res.status(200).json({ permissionGroup });
    } catch (error) {
      return errorhandler(error, res);
    }
  } else if (req.method === "PATCH") {
    // PATCH /api/teams/:teamId/datarooms/:id/permission-groups/:permissionGroupId
    const session = await getServerSession(req, res, authOptions);
    if (!session) {
      return res.status(401).end("Unauthorized");
    }

    const {
      teamId,
      id: dataroomId,
      permissionGroupId,
    } = req.query as {
      teamId: string;
      id: string;
      permissionGroupId: string;
    };

    const userId = (session.user as CustomUser).id;

    try {
      // Verify team membership
      const team = await prisma.team.findUnique({
        where: {
          id: teamId,
          users: {
            some: { userId },
          },
        },
      });

      if (!team) {
        return res.status(401).end("Unauthorized");
      }

      // Verify dataroom exists and belongs to team
      const dataroom = await prisma.dataroom.findUnique({
        where: {
          id: dataroomId,
          teamId: teamId,
        },
      });

      if (!dataroom) {
        return res.status(404).json({ error: "Dataroom not found" });
      }

      // Verify permission group exists and belongs to dataroom
      const permissionGroup = await prisma.permissionGroup.findUnique({
        where: {
          id: permissionGroupId,
          dataroomId: dataroomId,
          teamId: teamId,
        },
      });

      if (!permissionGroup) {
        return res.status(404).json({ error: "Permission group not found" });
      }

      // Validate and update permission group
      const validationResult = patchPermissionGroupSchema.safeParse(req.body);
      if (!validationResult.success) {
        return res.status(400).json({
          error: "Invalid request body",
          details: validationResult.error.issues,
        });
      }

      const { name, description } = validationResult.data;

      const updatedPermissionGroup = await prisma.permissionGroup.update({
        where: {
          id: permissionGroupId,
        },
        data: {
          ...(name && { name }),
          ...(description !== undefined && { description }),
        },
      });

      return res.status(200).json({ permissionGroup: updatedPermissionGroup });
    } catch (error) {
      return errorhandler(error, res);
    }
  } else if (req.method === "PUT") {
    // PUT /api/teams/:teamId/datarooms/:id/permission-groups/:permissionGroupId
    const session = await getServerSession(req, res, authOptions);
    if (!session) {
      return res.status(401).end("Unauthorized");
    }

    const {
      teamId,
      id: dataroomId,
      permissionGroupId,
    } = req.query as {
      teamId: string;
      id: string;
      permissionGroupId: string;
    };

    const { permissions } = req.body;

    const userId = (session.user as CustomUser).id;

    try {
      // Verify team membership
      const team = await prisma.team.findUnique({
        where: {
          id: teamId,
          users: {
            some: { userId },
          },
        },
      });

      if (!team) {
        return res.status(401).end("Unauthorized");
      }

      // Verify dataroom exists and belongs to team
      const dataroom = await prisma.dataroom.findUnique({
        where: {
          id: dataroomId,
          teamId: teamId,
        },
      });

      if (!dataroom) {
        return res.status(404).json({ error: "Dataroom not found" });
      }

      // Verify permission group exists and belongs to dataroom
      const permissionGroup = await prisma.permissionGroup.findUnique({
        where: {
          id: permissionGroupId,
          dataroomId: dataroomId,
          teamId: teamId,
        },
      });

      if (!permissionGroup) {
        return res.status(404).json({ error: "Permission group not found" });
      }

      // Validate permissions payload using Zod
      if (!permissions) {
        return res.status(400).json({ error: "Permissions are required" });
      }

      // Validate schema structure
      const validationResult = permissionsSchema.safeParse(permissions);
      if (!validationResult.success) {
        return res.status(400).json({
          error: "Invalid permissions format",
          details: validationResult.error.issues,
        });
      }

      const validatedPermissions = validationResult.data;

      const updatedPermissionGroup = await prisma.$transaction(async (tx) => {
        // Get existing permissions for comparison
        const existingPermissions =
          await tx.permissionGroupAccessControls.findMany({
            where: {
              groupId: permissionGroupId,
            },
          });

        // Create maps for efficient lookup
        const existingMap = new Map(
          existingPermissions.map((p) => [`${p.itemId}-${p.itemType}`, p]),
        );

        // Categorize permissions into updates vs creates
        const toUpdate: Array<{
          itemId: string;
          itemType: ItemType;
          canView: boolean;
          canDownload: boolean;
          canDownloadOriginal: boolean;
        }> = [];

        const toCreate: Array<{
          groupId: string;
          itemId: string;
          itemType: ItemType;
          canView: boolean;
          canDownload: boolean;
          canDownloadOriginal: boolean;
        }> = [];

        // Categorize permissions into updates vs creates
        Object.entries(validatedPermissions).forEach(([itemId, permission]) => {
          const key = `${itemId}-${permission.itemType}`;
          const existing = existingMap.get(key);

          const permissionData = {
            itemId,
            itemType: permission.itemType,
            canView: permission.view,
            canDownload: permission.download,
            canDownloadOriginal: false,
          };

          if (existing) {
            // Check if anything actually changed
            if (
              existing.canView !== permission.view ||
              existing.canDownload !== permission.download
            ) {
              toUpdate.push(permissionData);
            }
          } else {
            toCreate.push({
              groupId: permissionGroupId,
              ...permissionData,
            });
          }
        });

        // Perform updates
        if (toUpdate.length > 0) {
          await Promise.all(
            toUpdate.map((item) =>
              tx.permissionGroupAccessControls.updateMany({
                where: {
                  groupId: permissionGroupId,
                  itemId: item.itemId,
                  itemType: item.itemType,
                },
                data: {
                  canView: item.canView,
                  canDownload: item.canDownload,
                  canDownloadOriginal: item.canDownloadOriginal,
                },
              }),
            ),
          );
        }

        // Perform creates
        if (toCreate.length > 0) {
          await tx.permissionGroupAccessControls.createMany({
            data: toCreate,
          });
        }

        // Remove permissions that are no longer in the new set
        const newItemKeys = new Set(
          Object.entries(validatedPermissions).map(
            ([itemId, permission]) => `${itemId}-${permission.itemType}`,
          ),
        );

        const toDelete = existingPermissions.filter(
          (p) => !newItemKeys.has(`${p.itemId}-${p.itemType}`),
        );

        if (toDelete.length > 0) {
          await tx.permissionGroupAccessControls.deleteMany({
            where: {
              id: {
                in: toDelete.map((p) => p.id),
              },
            },
          });
        }

        return permissionGroup;
      });

      // After saving permissions, ensure parent folders are visible for any items that were made visible
      await ensureParentFoldersVisible(
        dataroomId,
        permissionGroupId,
        validatedPermissions,
      );

      return res.status(200).json({ permissionGroup: updatedPermissionGroup });
    } catch (error) {
      return errorhandler(error, res);
    }
  } else if (req.method === "DELETE") {
    // DELETE /api/teams/:teamId/datarooms/:id/permission-groups/:permissionGroupId
    const session = await getServerSession(req, res, authOptions);
    if (!session) {
      return res.status(401).end("Unauthorized");
    }

    const {
      teamId,
      id: dataroomId,
      permissionGroupId,
    } = req.query as {
      teamId: string;
      id: string;
      permissionGroupId: string;
    };

    const userId = (session.user as CustomUser).id;

    try {
      // Verify team membership
      const team = await prisma.team.findUnique({
        where: {
          id: teamId,
          users: {
            some: { userId },
          },
        },
      });

      if (!team) {
        return res.status(401).end("Unauthorized");
      }

      // Verify dataroom exists and belongs to team
      const dataroom = await prisma.dataroom.findUnique({
        where: {
          id: dataroomId,
          teamId: teamId,
        },
      });

      if (!dataroom) {
        return res.status(404).json({ error: "Dataroom not found" });
      }

      // Verify permission group exists and belongs to dataroom
      const permissionGroup = await prisma.permissionGroup.findUnique({
        where: {
          id: permissionGroupId,
          dataroomId: dataroomId,
          teamId: teamId,
        },
      });

      if (!permissionGroup) {
        return res.status(404).json({ error: "Permission group not found" });
      }

      // Delete the permission group (this will cascade delete access controls)
      await prisma.permissionGroup.delete({
        where: {
          id: permissionGroupId,
        },
      });

      return res.status(200).json({ message: "Permission group deleted" });
    } catch (error) {
      return errorhandler(error, res);
    }
  }

  // We only allow GET, PATCH, PUT, and DELETE requests
  res.setHeader("Allow", ["GET", "PATCH", "PUT", "DELETE"]);
  return res.status(405).end(`Method ${req.method} Not Allowed`);
}

