export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse,
) {
  if (req.method !== "POST") {
    return res.status(405).json({ message: "Method not allowed" });
  }

  // POST /api/teams/:teamId/datarooms/:id/groups/:groupId/permissions
  const session = await getServerSession(req, res, authOptions);
  if (!session) {
    res.status(401).end("Unauthorized");
    return;
  }

  const userId = (session.user as CustomUser).id;
  const {
    teamId,
    id: dataroomId,
    groupId,
  } = req.query as {
    teamId: string;
    id: string;
    groupId: string;
  };

  try {
    const { permissions } = req.body as {
      permissions: Record<
        string,
        { itemType: ItemType; view: boolean; download: boolean }
      >;
    };

    // Validate input
    if (!permissions) {
      return res.status(400).json({ message: "Missing required fields" });
    }

    // Check if the user is part of the team
    const team = await prisma.team.findUnique({
      where: {
        id: teamId,
        users: {
          some: {
            userId,
          },
        },
      },
    });

    if (!team) {
      return res.status(403).json({ message: "Unauthorized" });
    }

    const existingPermissions = await prisma.viewerGroupAccessControls.findMany(
      {
        where: {
          groupId,
          group: { dataroomId },
        },
        select: { itemId: true, itemType: true },
      },
    );

    const existingSet = new Set(
      existingPermissions.map((p) => `${p.itemId}-${p.itemType}`),
    );

    const toUpdate: {
      groupId: string;
      itemId: string;
      itemType: ItemType;
      canView: boolean;
      canDownload: boolean;
    }[] = [];
    const toCreate: {
      groupId: string;
      itemId: string;
      itemType: ItemType;
      canView: boolean;
      canDownload: boolean;
    }[] = [];

    Object.entries(permissions).forEach(([itemId, itemPermissions]) => {
      const key = `${itemId}-${itemPermissions.itemType}`;
      const data = {
        groupId,
        itemId,
        itemType: itemPermissions.itemType,
        canView: itemPermissions.view,
        canDownload: itemPermissions.download,
      };

      if (existingSet.has(key)) {
        toUpdate.push(data);
      } else {
        toCreate.push(data);
      }
    });

    console.log("toUpdate", toUpdate);
    console.log("toCreate", toCreate);

    // Perform operations
    await prisma.$transaction(async (tx) => {
      if (toUpdate.length > 0) {
        await Promise.all(
          toUpdate.map((item) =>
            tx.viewerGroupAccessControls.update({
              where: {
                groupId_itemId: {
                  groupId: item.groupId,
                  itemId: item.itemId,
                },
              },
              data: {
                canView: item.canView,
                canDownload: item.canDownload,
              },
            }),
          ),
        );
      }

      if (toCreate.length > 0) {
        await tx.viewerGroupAccessControls.createMany({
          data: toCreate,
        });
      }
    });

    // After saving permissions, ensure parent folders are visible for any items that were made visible
    await ensureParentFoldersVisible(dataroomId, groupId, permissions);

    res.status(200).json({ message: "Permissions updated successfully" });
  } catch (error) {
    console.error("Error updating permissions:", error);
    res.status(500).json({ message: "Internal server error" });
  }
}

import { useEffect, useState } from "react";

import { DEFAULT_LINK_TYPE } from ".";
import LinkItem from "./link-item";
import { LinkUpgradeOptions } from "./link-options";

export default function EmailAuthenticationSection({
  data,
  setData,
  isAllowed,
  handleUpgradeStateChange,
}: {
  data: DEFAULT_LINK_TYPE;
  setData: React.Dispatch<React.SetStateAction<DEFAULT_LINK_TYPE>>;
  isAllowed: boolean;
  handleUpgradeStateChange: ({
    state,
    trigger,
    plan,
    highlightItem,
  }: LinkUpgradeOptions) => void;
}) {
  const { emailProtected, emailAuthenticated, enableConversation } = data;
  const [enabled, setEnabled] = useState<boolean>(emailAuthenticated);

  useEffect(() => {
    setEnabled(emailAuthenticated);
  }, [emailAuthenticated]);

  const handleEnableAuthentication = () => {
    const updatedEmailAuthentication = !enabled;
    setData({
      ...data,
      emailProtected: updatedEmailAuthentication ? true : emailProtected,
      emailAuthenticated: updatedEmailAuthentication,
      enableConversation: updatedEmailAuthentication
        ? enableConversation
        : false,
    });
    setEnabled(updatedEmailAuthentication);
  };

  return (
    <div className="pb-5">
      <LinkItem
        title="Require email verification"
        link="https://www.papermark.com/help/article/require-email-verification"
        tooltipContent="Users must verify their email before accessing the content."
        enabled={enabled}
        action={handleEnableAuthentication}
        isAllowed={isAllowed}
        requiredPlan="business"
        upgradeAction={() =>
          handleUpgradeStateChange({
            state: true,
            trigger: "link_sheet_email_auth_section",
            plan: "Business",
            highlightItem: ["email-verify"],
          })
        }
      />
    </div>
  );
}

